create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text default '',role text not null default 'user' check(role in ('user','admin')),created_at timestamptz default now());
create table if not exists public.wallets(user_id uuid primary key references auth.users(id) on delete cascade,article_credits integer not null default 0 check(article_credits>=0),updated_at timestamptz default now());
create table if not exists public.articles(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,content text not null,status text not null default 'draft',created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.article_plans(id uuid primary key default gen_random_uuid(),name text not null,credits integer not null check(credits>0),price_cents integer not null check(price_cents>0),currency text not null default 'USD',active boolean not null default true);
create table if not exists public.payment_orders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),plan_id uuid references public.article_plans(id),provider text not null,provider_order_id text unique not null,amount_usd numeric not null,credits integer not null,status text not null default 'created',created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.credit_transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),credits integer not null,kind text not null,created_at timestamptz default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')) on conflict(id) do nothing;insert into public.wallets(user_id,article_credits) values(new.id,0) on conflict(user_id) do nothing;return new;end $$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.consume_article_credit(p_user_id uuid,p_article_id uuid default null) returns boolean language plpgsql security definer set search_path=public as $$declare c integer;begin select article_credits into c from public.wallets where user_id=p_user_id for update;if coalesce(c,0)<1 then return false;end if;update public.wallets set article_credits=article_credits-1,updated_at=now() where user_id=p_user_id;insert into public.credit_transactions(user_id,credits,kind) values(p_user_id,-1,'export');return true;end $$;
alter table public.profiles enable row level security;alter table public.wallets enable row level security;alter table public.articles enable row level security;alter table public.article_plans enable row level security;alter table public.payment_orders enable row level security;alter table public.credit_transactions enable row level security;
create policy "profiles own" on public.profiles for select using(auth.uid()=id);
create policy "wallet own" on public.wallets for select using(auth.uid()=user_id);
create policy "articles own" on public.articles for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "plans public" on public.article_plans for select using(active=true);
insert into public.article_plans(name,credits,price_cents,currency,active) values('أساسي',5,500,'USD',true),('احترافي',20,1200,'USD',true),('مميز',50,2500,'USD',true) on conflict do nothing;
